        return (y, b)  # DMY, DD/MM/YYYY, DD.MM.YYYY
    m = re.match(r'^(\d{4})(\d{2})(\d{2})$', s)
    if m:
        return (int(m.group(1)), int(m.group(2)))
    if re.match(r'^\d+(\.\d+)?$', s):
        d = date(1899, 12, 30) + timedelta(days=int(float(s)))
