def logical_lines(text, delim):
    lines = text.split('\n')
    if lines and lines[-1] == '':
        lines.pop()
    i = 0
    n = len(lines)
    while i < n:
        l = lines[i].rstrip('\r')
        i += 1
        if l.startswith('#'):
            yield ('comment', l)
            continue
        if not l.strip():
            continue
        if delim == ',':
            while l.count('"') % 2 == 1 and i < n:
                l += '\n' + lines[i].rstrip('\r')
                i += 1
        yield ('row', l)


def parse_delimited(depot, text):
    delim = DELIM[depot]
    hc = HC[depot]
    names = COLS[depot]
    seq = None
    date_form = BASE_DATE[depot]
    unit_dir = None
    header = None
    out = []
    for kind, l in logical_lines(text, delim):
        if kind == 'comment':
            m = re.match(r'#\s*seq\s*[:=]\s*(\d+)', l, re.I) or re.match(r'#\S* export seq=(\d+)', l, re.I)
            if m:
                if seq is None:
                    seq = int(m.group(1))
                continue
            m = re.match(r'#\s*([^:=]+?)\s*:\s*(.*?)\s*$', l)
            if m:
                k, v = m.group(1).lower(), m.group(2)
                if k in ('dates', 'date format', 'date', 'dateformat'):
                    date_form = v.split()[0] if v else date_form
                elif k in ('unit', 'weight unit', 'weight-unit'):
                    mu = re.match(r'(kg|g|lb|oz)\b', v.strip().lower())
                    if mu:
                        unit_dir = mu.group(1)
            continue
        if delim == ',':
            row = next(csv.reader([l]))
        else:
            row = l.split(delim)
        low = [c.strip().lower() for c in row]
        if all(c in names for c in low):
            header = low
            continue
        if header is None:
            continue
        if low and low[0] == 'total':
            continue
        widx = None
        for cand in hc['w']:
            if cand in header:
                widx = header.index(cand)
                break
        if widx is None:
            continue
        row_unit = None
        if len(row) == len(header) + 1:
            cand = row[widx + 1].strip().lower()
            if cand in FACT:
                row_unit = cand
                row = row[:widx + 1] + row[widx + 2:]
        if len(row) != len(header):
            continue
        d = dict(zip(header, row))
        wname = header[widx]
        unit = BASE_UNIT[depot]
        if unit_dir:
            unit = unit_dir
        if row_unit:
            unit = row_unit
        mu = re.search(r'_(kg|g|lb|oz)$', wname)
        if mu:
            unit = mu.group(1)
        typ = rtype(d.get(hc['type']))
        idt = d.get(hc['id'])
        st = d.get(hc['status'], '')
        if depot == 'harbor':
            st = HARBOR_ST.get(st.strip().lower(), st)
        if typ == 'void':
            r = mk(idt, 'void', None, None, '')
        else:
            kg = parse_weight(d[wname], dec_comma=(depot == 'west'), unit=unit)
            ym = parse_date(d.get(hc['ship']), date_form)
            r = mk(idt, typ, ym, kg, st)
        if r:
            out.append(r)
    return seq, out


