def parse_fixed(text):
    seq = None
    cur = None
    out = []
    bylen = {v['len']: k for k, v in LAYOUTS.items()}
    for line in text.split('\n'):
        line = line.rstrip('\r')
        if line.startswith('#LAYOUT'):
            parts = line.split()
            if len(parts) > 1 and parts[1] in LAYOUTS:
                cur = parts[1]
            continue
        if line.startswith('#SEQ'):
            m = re.search(r'\d+', line)
            if m and seq is None:
                seq = int(m.group())
            continue
        if line.startswith('#') or line.startswith('\f') or not line.strip():
            continue
        if 'SHIPMENT LISTING' in line:
            continue
        lay = bylen.get(len(line))
        if lay is None:
            if cur is None:
                continue
            lay = cur
            line = line.ljust(LAYOUTS[lay]['len'])[:LAYOUTS[lay]['len']]
        L = LAYOUTS[lay]

        def f(k):
            return line[L[k][0]:L[k][1]]
        typ = rtype(f('type'))
        idt = f('id').strip()
        if typ == 'void':
            r = mk(idt, 'void', None, None, '')
        else:
            s = f('ship')
            try:
                if L['sf'] == 'doy':
                    d = date(int(s[:4]), 1, 1) + timedelta(days=int(s[4:]) - 1)
                else:
                    d = date(int(s[:4]), int(s[4:6]), int(s[6:8]))
                ym = (d.year, d.month)
            except ValueError:
                ym = None
            try:
                kg = int(f('w')) * L['wu']
            except ValueError:
                kg = None
            r = mk(idt, typ, ym, kg, FW_ST.get(f('st').strip().upper(), f('st')))
        if r:
            out.append(r)
    return seq, out


# ---------------- json
def parse_json(text):
    seq = None
    out = []
    for line in text.split('\n'):
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        try:
            v = json.loads(line)
        except ValueError:
            continue
        objs = v if isinstance(v, list) else [v]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if 'meta' in o and isinstance(o['meta'], dict):
                if seq is None and 'seq' in o['meta']:
                    seq = int(o['meta']['seq'])
                continue
            typ = rtype(o.get('kind'))
            idt = str(o.get('id', ''))
            if typ == 'void':
                r = mk(idt, 'void', None, None, '')
            else:
                kg = None
                for k, val in o.items():
                    m = re.match(r'^weight_(kg|g|lb|oz)$', k)
                    if m and val is not None:
                        kg = parse_weight(str(val), unit=m.group(1))
                if kg is None and 'weight' in o:
                    kg = parse_weight(str(o['weight']), unit='kg')
                r = mk(idt, typ, parse_date(str(o.get('shipped_at', '')), 'iso'), kg, str(o.get('status', '')))
            if r:
                out.append(r)
    return seq, out


