def parse_xml(b):
    root = ET.fromstring(b)
    seq = int(root.get('seq')) if (root.get('seq') or '').isdigit() else None
    ru = (root.get('weight-unit') or 'kg').lower()
    out = []
    for el in root.iter():
        if el.tag.split('}')[-1] != 'shipment':
            continue
        typ = rtype(el.get('type'))
        idt = el.get('id', '')
        if typ == 'void':
            r = mk(idt, 'void', None, None, '')
        else:
            def child(n):
                for c in el:
                    if c.tag.split('}')[-1] == n:
                        return c
            w = child('weight')
            kg = None
            if w is not None and (w.text or '').strip():
                kg = parse_weight(w.text, unit=(w.get('unit') or el.get('weight-unit') or ru).lower())
            sh = el.get('shipped')
            c = child('shipped')
            if c is not None and (c.text or '').strip():
                sh = c.text
            st = child('status')
            r = mk(idt, typ, parse_date(sh, 'iso'), kg, st.text if st is not None else '')
        if r:
            out.append(r)
    return seq, out


